import { ToggleButton as ToggleButtonPrimitive } from "@kobalte/core/toggle-button";
import { type ComponentProps, splitProps } from "solid-js";
import { cn } from "@/lib/utils";

const toggleVariantClasses = {
  default: "bg-transparent",
  outline: "border border-input bg-transparent hover:bg-muted",
};

const toggleSizeClasses = {
  default: "h-7 min-w-7 px-2 has-data-[icon=inline-end]:pr-1.5 has-data-[icon=inline-start]:pl-1.5",
  sm: "h-6 min-w-6 rounded-[min(var(--radius-md),8px)] px-2 text-[0.625rem] has-data-[icon=inline-end]:pr-1.5 has-data-[icon=inline-start]:pl-1.5 [&_svg:not([class*='size-'])]:size-3",
  lg: "h-8 min-w-8 px-2.5 has-data-[icon=inline-end]:pr-2 has-data-[icon=inline-start]:pl-2",
};

export type ToggleVariant = keyof typeof toggleVariantClasses;
export type ToggleSize = keyof typeof toggleSizeClasses;

export function toggleVariants(options?: {
  variant?: ToggleVariant;
  size?: ToggleSize;
  class?: string;
}) {
  return cn(
    "group/toggle inline-flex items-center justify-center gap-1 rounded-md text-xs font-medium whitespace-nowrap transition-all outline-none hover:bg-muted hover:text-foreground focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 disabled:pointer-events-none disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-destructive/20 data-pressed:bg-muted dark:aria-invalid:ring-destructive/40 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
    toggleVariantClasses[options?.variant ?? "default"],
    toggleSizeClasses[options?.size ?? "default"],
    options?.class,
  );
}

type ToggleProps = ComponentProps<typeof ToggleButtonPrimitive> & {
  variant?: ToggleVariant;
  size?: ToggleSize;
};

export function Toggle(props: ToggleProps) {
  const [, rest] = splitProps(props, ["class", "ref", "variant", "size"]);
  return (
    <ToggleButtonPrimitive
      ref={props.ref}
      data-slot="toggle"
      class={toggleVariants({ variant: props.variant, size: props.size, class: props.class })}
      {...rest}
    />
  );
}
